WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, CASE WHEN island_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS island_id_tier, COUNT(CASE WHEN method = 'paypal' THEN 1 END) AS paypal_count, COUNT(DISTINCT method) AS distinct_methods, AVG(amount) FILTER (WHERE status = 'FAILED') AS failed_avg_amount FROM sessions_payments GROUP BY CUBE (DATE_TRUNC('WEEK', paid_at), CASE WHEN island_id >= 8 THEN 'LARGE' ELSE 'SMALL' END) HAVING paypal_count >= 1 ORDER BY week_start;
